package com.crewbeat.hondabox.tests;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import com.crewbeat.hondabox.*;import java.util.*;
/** Offline guide UI and settings fallback; no vehicle fixture needed. */
public final class SetupGuideTests extends Instrumentation {
 private Activity activity;private int checks;private final ProbeState state=ProbeState.INSTANCE;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 private void main(Runnable task){Throwable[] error={null};runOnMainSync(()->{try{task.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError("UI action",error[0]);}
 private AlertDialog dialog()throws Exception{java.lang.reflect.Field field=SettingsScreenActivity.class.getDeclaredField("setupGuide");field.setAccessible(true);Object guide=field.get(activity);field=BackgroundSetupGuide.class.getDeclaredField("dialog");field.setAccessible(true);return (AlertDialog)field.get(guide);}
 private void image(Context c,String name)throws Exception{SystemClock.sleep(600);Bitmap b=getUiAutomation().takeScreenshot();try(java.io.OutputStream out=new java.io.FileOutputStream(new java.io.File(c.getExternalFilesDir(null),name))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> item:values.entrySet()){Object v=item.getValue();String k=item.getKey();if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);}e.commit();}
 @Override public void onStart(){Context c=getTargetContext();Bundle result=new Bundle();int outcome=Activity.RESULT_OK;String theme=ThemeSettings.mode(c),language=I18n.language(c);SharedPreferences bg=c.getSharedPreferences("background",0);Map<String,?> old=new HashMap<>(bg.getAll());if(!Build.HARDWARE.contains("ranchu")&&!Build.HARDWARE.contains("goldfish")){result.putString("failure","Emulator only; no state changed");finish(1,result);return;}try{
  if(!Build.HARDWARE.contains("ranchu")&&!Build.HARDWARE.contains("goldfish"))throw new AssertionError("Emulator only");BackgroundSettings.stop(c);SystemClock.sleep(350);state.newSession();state.running(false);
  for(String mode:new String[]{ThemeSettings.DAY,ThemeSettings.NIGHT})for(String lang:new String[]{"en","ru"}){
   ThemeSettings.mode(c,mode);I18n.language(c,lang);activity=startActivitySync(new Intent(c,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();
   for(String page:new String[]{"fyt","dudu","check"}){
    Button button=activity.findViewById(android.R.id.content).findViewWithTag("setup-guide-"+page);check(button!=null,"guide entry exists");main(()->button.requestRectangleOnScreen(new Rect(0,0,button.getWidth(),button.getHeight()),true));waitForIdleSync();check(button.getWidth()<((View)button.getParent()).getWidth(),"guide button remains intrinsic width");main(()->button.performClick());waitForIdleSync();AlertDialog guide=dialog();check(guide!=null&&guide.isShowing(),"guide opens");ScrollView scroll=guide.getWindow().getDecorView().findViewWithTag("setup-guide-content");check(scroll!=null&&scroll.canScrollVertically(1),"long guide can scroll in head-unit window");Button close=guide.getButton(AlertDialog.BUTTON_POSITIVE);check(close.isShown()&&close.getHeight()>0,"close stays visible independently of text");check(!state.overlaySnapshot().running&&!state.overlaySnapshot().commandBusy,"reading help neither starts service nor sends commands");
    if(lang.equals("ru")&&page.equals("dudu"))image(c,"setup-dudu-"+mode+"-TEST.png");main(()->scroll.fullScroll(View.FOCUS_DOWN));waitForIdleSync();check(scroll.getScrollY()>0&&!scroll.canScrollVertically(1),"guide reaches final instructions");main(()->close.performClick());waitForIdleSync();check(!guide.isShowing(),"guide closes");
   }
   main(()->activity.finish());waitForIdleSync();activity=null;
  }
  ThemeSettings.mode(c,ThemeSettings.DAY);I18n.language(c,"en");activity=startActivitySync(new Intent(c,SettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));main(()->activity.findViewById(android.R.id.content).findViewWithTag("setup-guide-fyt").performClick());waitForIdleSync();
  ActivityMonitor monitor=addMonitor(new IntentFilter(Settings.ACTION_SETTINGS),new ActivityResult(Activity.RESULT_OK,null),true);AlertDialog guide=dialog();main(()->guide.getButton(AlertDialog.BUTTON_NEUTRAL).performClick());waitForIdleSync();SystemClock.sleep(150);check(monitor.getHits()==1,"missing FYT settings falls back to Android Settings on user tap");removeMonitor(monitor);check(!state.overlaySnapshot().running,"settings navigation does not start service");
  result.putString("result","PASS: "+checks+" setup guide interactions in RU/EN and day/night; scroll, close, compact buttons and Android fallback");
 }catch(Throwable e){outcome=1;result.putString("failure",android.util.Log.getStackTraceString(e));}finally{if(activity!=null)main(()->activity.finish());ThemeSettings.mode(c,theme);I18n.language(c,language);restore(bg,old);((android.app.job.JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE)).cancel(BackgroundRecovery.JOB_ID);state.newSession();state.running(false);}finish(outcome,result);}
}
